17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.ArrayList;
24	import java.util.Collection;
25	import java.util.List;
26	import java.util.Locale;
27	import java.util.regex.Pattern;
28	
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
40	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
41	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
42	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
43	import org.springframework.samples.petclinic.rest.api.OwnersApi;
44	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
45	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.PetDto;
47	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
70	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
71	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
72	     */
73	    private static final Pattern EMAIL_PATTERN =
74	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
75	
76	    private final ClinicService clinicService;
77	
78	    private final OwnerMapper ownerMapper;
79	
80	    private final PetMapper petMapper;
81	
82	    private final VisitMapper visitMapper;
83	
84	    public OwnerRestControllerV1(ClinicService clinicService,
85	                                 OwnerMapper ownerMapper,
86	                                 PetMapper petMapper,
87	                                 VisitMapper visitMapper) {
88	        this.clinicService = clinicService;
89	        this.ownerMapper = ownerMapper;
90	        this.petMapper = petMapper;
91	        this.visitMapper = visitMapper;
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
97	        Collection<Owner> owners;
98	        if (lastName != null) {
99	            owners = this.clinicService.findOwnerByLastName(lastName);
100	        } else {
101	            owners = this.clinicService.findAllOwners();
102	        }
103	        if (owners.isEmpty()) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
107	    }
108	
109	    /**
110	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
111	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
112	     */
113	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
114	        List<String> missing = new ArrayList<>();
115	        if (isBlank(ownerFieldsDto.getFirstName())) {
116	            missing.add("firstName");
117	        }
118	        if (isBlank(ownerFieldsDto.getLastName())) {
119	            missing.add("lastName");
120	        }
121	        if (isBlank(ownerFieldsDto.getAddress())) {
122	            missing.add("address");
123	        }
124	        if (isBlank(ownerFieldsDto.getCity())) {
125	            missing.add("city");
126	        }
127	        if (isBlank(ownerFieldsDto.getTelephone())) {
128	            missing.add("telephone");
129	        }
130	        if (!missing.isEmpty()) {
131	            throw new RequiredFieldsMissingException(missing);
132	        }
133	    }
134	
135	    private static boolean isBlank(String value) {
136	        return value == null || value.isBlank();
137	    }
138	
139	    /**
140	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
141	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
142	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
143	     * normalized value is what gets stored, returned and used for every address comparison; a value
144	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
145	     * rejects it.
146	     *
147	     * @param address the raw address as supplied by the caller, may be {@code null}
148	     * @return the normalized address ({@code ""} when blank or {@code null})
149	     */
150	    private static String normalizeAddress(String address) {
151	        if (address == null) {
152	            return "";
153	        }
154	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
155	        if (collapsed.isEmpty()) {
156	            return "";
157	        }
158	        String[] tokens = collapsed.split(" ");
159	        StringBuilder sb = new StringBuilder(collapsed.length());
160	        for (int i = 0; i < tokens.length; i++) {
161	            String token = tokens[i];
162	            switch (token) {
163	                case "ST" -> token = "STREET";
164	                case "RD" -> token = "ROAD";
165	                case "AVE" -> token = "AVENUE";
166	                default -> { }
167	            }
168	            if (i > 0) {
169	                sb.append(' ');
170	            }
171	            sb.append(token);
172	        }
173	        return sb.toString();
174	    }
175	
176	    /**
177	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
178	     * A leading {@code +} and its country code are kept as given; otherwise the country code
179	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
180	     * The result must carry 8 to 15 digits after the {@code +}. Returns the E.164 string to be
181	     * stored and returned.
182	     *
183	     * @param telephone the raw telephone as supplied by the caller
184	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
185	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
186	     */
187	    private static String normalizeTelephone(String telephone) {
188	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
189	        String e164;
190	        if (cleaned.startsWith("+")) {
191	            e164 = "+" + cleaned.substring(1);
192	        } else {
193	            String national = cleaned;
194	            if (national.startsWith("0")) {
195	                national = national.substring(1);
196	            }
197	            e164 = "+61" + national;
198	        }
199	        String digits = e164.substring(1);
200	        if (!digits.matches("\\d{8,15}")) {
201	            throw new InvalidTelephoneException(
202	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
203	        }
204	        return e164;
205	    }
206	
207	    /**
208	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
209	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
210	     *
211	     * @param email the raw email as supplied by the caller, may be {@code null}
212	     * @return the lower-cased email, or {@code null} when none was supplied
213	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
214	     */
215	    private static String normalizeEmail(String email) {
216	        if (email == null || email.isBlank()) {
217	            return null;
218	        }
219	        String trimmed = email.trim();
220	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
221	            throw new InvalidEmailException("Email must be a syntactically valid address");
222	        }
223	        return trimmed.toLowerCase(Locale.ROOT);
224	    }
225	
226	    /**
227	     * Rejects a create whose E.164 telephone is already used by any existing owner, so that
228	     * telephones stay unique across owners. Telephones are stored in E.164 form on create, so a
229	     * direct equality comparison of the E.164 values against the stored values is sufficient.
230	     *
231	     * @param normalizedTelephone the E.164 telephone of the owner being created
232	     * @throws DuplicateTelephoneException if another owner already uses this telephone
233	     */
234	    private void rejectDuplicateTelephone(String normalizedTelephone) {
235	        boolean inUse = this.clinicService.findAllOwners().stream()
236	            .anyMatch(existing -> normalizedTelephone.equals(existing.getTelephone()));
237	        if (inUse) {
238	            throw new DuplicateTelephoneException(
239	                "Telephone is already used by another owner");
240	        }
241	    }
242	
243	    /**
244	     * Rejects a create that would place the owner in a household already occupied by another owner,
245	     * i.e. one whose last name and address match the supplied values. The two fields are compared
246	     * case-insensitively after whitespace is collapsed (leading/trailing whitespace trimmed and each
247	     * run of internal whitespace reduced to a single space), so {@code '110 W.  Liberty St. '} and
248	     * {@code '110 w. liberty st.'} are treated as the same address. The caller may bypass this check
249	     * by setting {@code sharesHousehold} to {@code true}.
250	     *
251	     * @param lastName the last name of the owner being created
252	     * @param address the address of the owner being created
253	     * @throws DuplicateHouseholdException if another owner already shares this last name and address
254	     */
255	    private void rejectDuplicateHousehold(String lastName, String address) {
256	        String normalizedLastName = normalizeForHousehold(lastName);
257	        String normalizedAddress = normalizeForHousehold(address);
258	        boolean inHousehold = this.clinicService.findAllOwners().stream()
259	            .anyMatch(existing ->
260	                normalizedLastName.equals(normalizeForHousehold(existing.getLastName()))
261	                    && normalizedAddress.equals(normalizeForHousehold(existing.getAddress())));
262	        if (inHousehold) {
263	            throw new DuplicateHouseholdException(
264	                "An owner with the same last name and address already exists");
265	        }
266	    }
267	
268	    /**
269	     * Normalizes a value for household comparison by trimming, collapsing every run of whitespace to
270	     * a single space and lower-casing, so the comparison is case-insensitive with collapsed whitespace.
271	     *
272	     * @param value the raw value, may be {@code null}
273	     * @return the normalized value ({@code ""} when {@code value} is {@code null})
274	     */
275	    private static String normalizeForHousehold(String value) {
276	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
277	    }
278	
279	    /**
280	     * Derives the stable household identifier for an owner from the normalized last name and address.
281	     * The value is a deterministic function of those two fields (compared case-insensitively with
282	     * collapsed whitespace, exactly as {@link #rejectDuplicateHousehold}), so every owner in the same
283	     * household — including owners who knowingly join it via {@code sharesHousehold} — is assigned the
284	     * same identifier without any existing record having to be updated. Formatted {@code 'HH-<HEX12>'}
285	     * where {@code HEX12} is the upper-cased first twelve hex characters of the SHA-256 of the two
286	     * normalized fields.
287	     *
288	     * @param lastName the last name of the owner being created
289	     * @param address the address of the owner being created
290	     * @return the stable household identifier
291	     */
292	    private static String householdId(String lastName, String address) {
293	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
294	        try {
295	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
296	            StringBuilder sb = new StringBuilder(digest.length * 2);
297	            for (byte b : digest) {
298	                sb.append(String.format("%02x", b));
299	            }
300	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
301	        } catch (NoSuchAlgorithmException e) {
302	            throw new IllegalStateException("SHA-256 not available", e);
303	        }
304	    }
305	
306	    /**
307	     * Builds the customer code assigned to an owner on create, formatted {@code '<LAST3>-<NNNN>'}
308	     * where {@code LAST3} is the upper-cased first three letters of the owner's last name and
309	     * {@code NNNN} is a global 4-digit zero-padded sequence equal to one more than the current
310	     * number of owners, e.g. {@code 'SMI-0007'}.
311	     *
312	     * @param lastName the last name of the owner being created
313	     * @return the formatted customer code
314	     */
315	    private String nextCustomerCode(String lastName) {
316	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
317	        int sequence = this.clinicService.findAllOwners().size() + 1;
318	        return String.format("%s-%04d", last3, sequence);
319	    }
320	
321	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
322	    @Override
323	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
324	        Owner owner = this.clinicService.findOwnerById(ownerId);
325	        if (owner == null) {
326	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
327	        }
328	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
329	    }
330	
331	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
332	    @Override
333	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
334	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
335	        validateRequiredFields(ownerFieldsDto);
336	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
337	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
338	        }
339	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
340	        rejectDuplicateTelephone(normalizedTelephone);
341	        ownerFieldsDto.setTelephone(normalizedTelephone);
342	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
343	        if (ownerFieldsDto.getRegistrationDate() == null) {
344	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
345	        }
346	        HttpHeaders headers = new HttpHeaders();
347	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
348	        owner.setCustomerCode(nextCustomerCode(ownerFieldsDto.getLastName()));
349	        owner.setHouseholdId(householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()));
350	        this.clinicService.saveOwner(owner);
351	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
352	        headers.setLocation(UriComponentsBuilder.newInstance()
353	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
354	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
355	    }
356	
357	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
358	    @Override
359	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
360	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
361	        if (currentOwner == null) {
362	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
363	        }
364	        currentOwner.setAddress(ownerFieldsDto.getAddress());
365	        currentOwner.setCity(ownerFieldsDto.getCity());
366	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
367	        currentOwner.setLastName(ownerFieldsDto.getLastName());
368	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
369	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
370	        this.clinicService.saveOwner(currentOwner);
371	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
372	    }
373	
374	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
375	    @Transactional
376	    @Override
377	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
378	        Owner owner = this.clinicService.findOwnerById(ownerId);
379	        if (owner == null) {
380	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
381	        }
382	        this.clinicService.deleteOwner(owner);
383	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
384	    }
385	
386	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
387	    @Override
388	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
389	        Owner owner = this.clinicService.findOwnerById(ownerId);
390	        if (owner == null) {
391	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
392	        }
393	        HttpHeaders headers = new HttpHeaders();
394	        Pet pet = petMapper.toPet(petFieldsDto);
395	        owner.setId(ownerId);
396	        pet.setOwner(owner);
397	        pet.getType().setName(null);
398	        this.clinicService.savePet(pet);
399	        PetDto petDto = petMapper.toPetDto(pet);
400	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
401	            .buildAndExpand(pet.getId()).toUri());
402	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
403	    }
404	
405	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
406	    @Override
407	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
408	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
409	        if (currentOwner != null) {
410	            Pet currentPet = this.clinicService.findPetById(petId);
411	            if (currentPet != null) {
412	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
413	                currentPet.setName(petFieldsDto.getName());
414	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
415	                this.clinicService.savePet(currentPet);
416	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
417	            }
418	        }
419	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
420	    }
421	
422	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
423	    @Override
424	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
425	        HttpHeaders headers = new HttpHeaders();
426	        Visit visit = visitMapper.toVisit(visitFieldsDto);
427	        Pet pet = new Pet();
428	        pet.setId(petId);
429	        visit.setPet(pet);
430	        this.clinicService.saveVisit(visit);
431	        VisitDto visitDto = visitMapper.toVisitDto(visit);
432	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
433	            .buildAndExpand(visit.getId()).toUri());
434	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
435	    }
436	
437	
438	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
439	    @Override
440	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
441	        Owner owner = this.clinicService.findOwnerById(ownerId);
442	        if (owner != null) {
443	            Pet pet = owner.getPet(petId);
444	            if (pet != null) {
445	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
446	            }
447	        }
448	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
449	    }
450	}
